  "n": 92,
  "breeds": "canecorso",
  "title": {
   "en": "Learning and thinking",
   "fr": "Apprendre et réfléchir"
  },
  "duration": 30,
  "xf": 0.4,
  "textIn": 0.4,
  "textOut": 0.3,
